describe('Search Filter Results Count Display', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display correct number of results for each filter option', () => {
    // Set up initial state with no filters applied
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Verify initial results count is displayed
    cy.get('[data-testid="results-count"]').should('be.visible');
    cy.get('[data-testid="results-count"]').should('contain', '0 results');

    // Apply first filter (price range)
    cy.get('[data-testid="price-filter-dropdown"]').click();
    cy.get('[data-testid="price-filter-option-100"]').click();
    cy.get('[data-testid="price-filter-option-200"]').click();

    // Verify results count updates
    cy.get('[data-testid="results-count"]').should('contain', '0 results');
    cy.get('[data-testid="results-count"]').should('contain', '100-200 results');

    // Apply second filter (brand)
    cy.get('[data-testid="brand-filter-dropdown"]').click();
    cy.get('[data-testid="brand-filter-option-apple"]').click();

    // Verify results count updates
    cy.get('[data-testid="results-count"]').should('contain', '100-200 results');
    cy.get('[data-testid="results-count"]').should('contain', 'Apple');

    // Apply third filter (category)
    cy.get('[data-testid="category-filter-dropdown"]').click();
    cy.get('[data-testid="category-filter-option-laptops"]').click();

    // Verify results count updates
    cy.get('[data-testid="results-count"]').should('contain', '100-200 results');
    cy.get('[data-testid="results-count"]').should('contain', 'Apple Laptops');

    // Verify results count is accurate
    cy.get('[data-testid="results-count"]').should('contain', '10 results');
  });

  it('should handle edge case when no results are found for a filter combination', () => {
    // Set up initial state with no filters applied
    cy.get('[data-testid="search-input"]').type('nonexistent product');
    cy.get('[data-testid="search-button"]').click();

    // Verify initial results count is displayed
    cy.get('[data-testid="results-count"]').should('be.visible');
    cy.get('[data-testid="results-count"]').should('contain', '0 results');

    // Apply filters
    cy.get('[data-testid="price-filter-dropdown"]').click();
    cy.get('[data-testid="price-filter-option-100"]').click();
    cy.get('[data-testid="brand-filter-dropdown"]').click();
    cy.get('[data-testid="brand-filter-option-apple"]').click();
    cy.get('[data-testid="category-filter-dropdown"]').click();
    cy.get('[data-testid="category-filter-option-laptops"]').click();

    // Verify results count updates to reflect no results
    cy.get('[data-testid="results-count"]').should('contain', '0 results');

    // Verify no results message is displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
  });
});
